package com.aistock.gateway;
import java.util.*;import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.web.servlet.FilterRegistrationBean;import org.springframework.web.cors.*;import org.springframework.web.filter.CorsFilter;
@Configuration public class AdminTaskCorsConfiguration {
 @Bean FilterRegistrationBean<CorsFilter> adminTaskCors(@Value("${aistock.auth.allowed-origins:http://127.0.0.1:15173,http://localhost:15173}")String origins){var c=new CorsConfiguration();c.setAllowedOrigins(Arrays.stream(origins.split(",")).map(String::strip).filter(s->!s.isEmpty()).toList());c.setAllowCredentials(true);c.setAllowedMethods(List.of("GET","OPTIONS"));c.setAllowedHeaders(List.of("Content-Type","X-Trace-Id"));var source=new UrlBasedCorsConfigurationSource();for(var part:List.of("users","predictions","tasks","market","http"))source.registerCorsConfiguration("/api/v1/admin/statistics/"+part,c);source.registerCorsConfiguration("/api/v1/admin/tasks",c);var write=new CorsConfiguration(c);write.setAllowedMethods(List.of("POST","OPTIONS"));write.setAllowedHeaders(List.of("Content-Type","X-Trace-Id","X-Aistock-Admin-Action"));source.registerCorsConfiguration("/api/v1/admin/tasks/*/retry",write);source.registerCorsConfiguration("/api/v1/admin/tasks/*/cancel",write);source.registerCorsConfiguration("/api/v1/admin/tasks/training/*/cancel",write);source.registerCorsConfiguration("/api/v1/admin/tasks/**",c);var filter=new CorsFilter(source){@Override protected void doFilterInternal(jakarta.servlet.http.HttpServletRequest r,jakarta.servlet.http.HttpServletResponse s,jakarta.servlet.FilterChain chain)throws java.io.IOException,jakarta.servlet.ServletException{s.setHeader("Cache-Control","no-store");if(!"OPTIONS".equals(r.getMethod())&&!ProxyHeaderPolicy.allowed(r.getMethod(),r.getRequestURI())){chain.doFilter(r,s);return;}super.doFilterInternal(r,s,chain);}};var bean=new FilterRegistrationBean<CorsFilter>(filter);bean.setOrder(-100);bean.addUrlPatterns("/api/v1/admin/tasks","/api/v1/admin/tasks/*","/api/v1/admin/statistics","/api/v1/admin/statistics/*");return bean;}
}
